from pathlib import Path
import yaml

for p in sorted(Path(r"G:\work\new\problems").glob("*/task.yaml")):
    d = yaml.safe_load(p.read_text(encoding="utf-8")) or {}
    task = d.setdefault("task", {})
    task["tips"] = (
        "- The final score is the last AUGMENTATION SCORE line printed by test_n.\n"
        "- test_n uses random test data (test_data_load.enable = False).\n"
        "- Do not generate run.py; test_train.py is generated by the code_error agent."
    )
    p.write_text(yaml.safe_dump(d, sort_keys=False, allow_unicode=True), encoding="utf-8")
print("updated tips")
